// Input validation
const input = $input.first().json;

// Validate required fields
if (!input.query || typeof input.query !== 'string' || input.query.trim().length === 0) {
  return {
    json: {
      success: false,
      error: 'Invalid input: query is required and must be a non-empty string',
      agentType: 'web_search',
      errorCode: 'INVALID_INPUT'
    }
  };
}

// Sanitize query - remove potentially harmful content
let sanitizedQuery = input.query.trim()
  .replace(/<[^>]*>/g, '') // Remove HTML tags
  .slice(0, 500); // Limit query length

return {
  json: {
    query: sanitizedQuery,
    sessionId: input.sessionId || $execution.id,
    startTime: Date.now(),
    metadata: {
      originalQueryLength: input.query.length,
      sanitizedQueryLength: sanitizedQuery.length,
      executionId: $execution.id
    }
  }
};

// Format successful output with sources
const input = $('Validate Input').first().json;
const result = $input.first().json;

const executionTime = Date.now() - (input.startTime || Date.now());

// Extract sources and search queries
let sources = [];
let searchQueries = [];

try {
  if (result.intermediateSteps) {
    for (const step of result.intermediateSteps) {
      // Track search queries
      if (step.action && step.action.toolInput) {
        searchQueries.push({
          tool: step.action.tool,
          query: step.action.toolInput
        });
      }

      // Extract sources from observations
      if (step.observation) {
        const obs = typeof step.observation === 'string' 
          ? step.observation 
          : JSON.stringify(step.observation);

        // Extract URLs
        const urlRegex = /https?:\/\/[^\s<>"'\]\)]+/g;
        const urls = obs.match(urlRegex) || [];
        for (const url of urls) {
          if (!sources.find(s => s.url === url)) {
            sources.push({
              url,
              type: url.includes('wikipedia') ? 'wikipedia' : 'web'
            });
          }
        }
      }
    }
  }
} catch (e) {
  // Non-critical parsing error
}

return {
  json: {
    success: true,
    agentType: 'web_search',
    output: result.output || 'Search completed',
    sources,
    searchQueries,
    resultCount: sources.length,
    metadata: {
      executionTime,
      toolCalls: searchQueries.length,
      executionId: input.metadata?.executionId
    }
  }
};

// Handle validation error
const input = $input.first().json;

return {
  json: {
    success: false,
    agentType: 'web_search',
    error: input.error || 'Validation failed',
    errorCode: input.errorCode || 'VALIDATION_ERROR',
    output: null,
    sources: [],
    metadata: {
      executionId: $execution.id
    }
  }
};
